@given(st.integers(min_value=0, max_value=10**9), st.integers(min_value=1, max_value=50))
def test_sums_back(cents, n):
    parts = split(cents, n)
    assert sum(parts) == cents and len(parts) == n and max(parts) - min(parts) <= 1
